query CalculateExpectedPaymentDelta($ids: [ID!]) {
  transactions(findTransactionsInput: {ids: $ids}) {
    edges {
      node {
        id
        amount
        amountWithDirection
        currency
        prettyAmountUnreconciledToExpectedPayment
        expectedPaymentDelta {
          unreconcilable
          expectedPaymentCount
          prettyExpectedPaymentAmount
          prettyTransactionExpectedPaymentDifference
          expectedPaymentIds
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
  abilities {
    ExpectedPayment {
      canReconcile
      canUnreconcile
      __typename
    }
    __typename
  }
}

