    input: {id: $id, paymentType: $paymentType, direction: $direction, amount: $amount, description: $description, vendorId: $vendorId, vendorCustomerId: $vendorCustomerId, asOfDate: $asOfDate, reconciled: $reconciled, posted: $posted, counterpartyId: $counterpartyId, currency: $currency, internalAccountIds: $internalAccountIds, connectionId: $connectionId, metadata: $metadata, reconciledItemTypes: $reconciledItemTypes, selectedTransactableIds: $selectedTransactableIds, selectedTransactableType: $selectedTransactableType, referenceNumber: $referenceNumber, bulkRequestId: $bulkRequestId, orderBy: $orderBy, reconciliationRuleId: $reconciliationRuleId, unledgered: $unledgered, unledgeredOrUnreconciled: $unledgeredOrUnreconciled}
  ) {
    totalCount
    creditCount
    debitCount
    totalAmount
    creditAmount
    debitAmount
    currency
    __typename
  }
}

query connectionView($id: ID!) {
  connection(id: $id) {
    id
    nickname
    entity
    vendor {
      id
      name
      __typename
    }
    currencies
    __typename
  }
}

query connectionsView {
  connections {
    totalCount
    nodes {
      id
      nickname
      canCustomerUploadFiles
      vendor {
        id
        name
        __typename
      }
      __typename
    }
    __typename
  }
}

query cpaCodesDropdown($direction: DirectionEnum) {
  cpaCodes(direction: $direction) {
    code
    description
    __typename
  }
}

mutation createFundFlow($input: CreateFundFlowInput!) {
  createFundFlow(input: $input) {
    fundFlow {
      id
      __typename
    }
    errors
    __typename
  }
}

mutation createLedgerAccountSettlement($input: CreateLedgerAccountSettlementInput!) {
  createLedgerAccountSettlement(input: $input) {
    ledgerAccountSettlement {
      id
      __typename
    }
    errors
    __typename
  }
}

mutation createReconciliationBatch($input: CreateReconciliationBatchInput!) {
  createReconciliationBatch(input: $input) {
    reconciliationBatch {
      id
      status
      internalAccountId
      internalAccountGroupId
      processAt
      __typename
    }
    __typename
  }
}
